export const SCAP_DEMO_CASES = Object.freeze(
  FIXTURES.map((item) =>
    Object.freeze({
      id: item.id,
      label: item.label,
      profile: item.request.source_profile,
    }),
  ),
);
export function scapDemoSource(id: string): {
  raw: ArrayBuffer;
  request: ScapRequest;
} {
  const item = FIXTURES.find((item) => item.id === id);
  if (!item) throw new ScapResponseError();
  const bytes = Uint8Array.from(atob(item.sourceBase64), (char) =>
    char.charCodeAt(0),
  );
  return {
    raw: bytes.buffer,
    request: JSON.parse(JSON.stringify(item.request)) as ScapRequest,
  };
}
export async function scapDemoResponse(
  raw: ArrayBuffer,
  request: ScapRequest,
  scenario = "",
): Promise<ScapResponse> {
  const item = FIXTURES.find((item) => item.id === scenario);
  if (!item) throw new ScapResponseError();
  const prepared = await prepareScapUpload(raw, request);
  const selected = await prepareScapUpload(
    scapDemoSource(item.id).raw,
    item.request,
  );
  if (
    prepared.expected.sourceSha256 !== item.sourceSha256 ||
    prepared.expected.sourceBytes !== item.sourceBytes ||
    prepared.query !== selected.query ||
    prepared.assertionHeader !== selected.assertionHeader
  )
    throw new ScapResponseError();
  return parseScapResponse(item.rawJson, prepared.expected);
}
